void Solver::bump_var(int var, double coeff) {
    // Compute increment once
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale if activity becomes too large to avoid overflow
    if (activity[var] > 1e100) {
        const double scale = 1e-100;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Update VSIDS heap only if the variable is present
    bool inHeap = vsids.inHeap(var);
    if (inHeap) {
        vsids.update(var);
    }
}
